"""Standalone job scraper for nielseniq.com (India roles). Generated by the agent; runs with NO LLM calls.
Run:  python scraper.py [output.jsonl]
source_type=rest_api, pagination=page_number.
"""

import json
import os
import sys
import time
import html as html_lib
from datetime import datetime
from urllib.parse import urljoin

import requests
from bs4 import BeautifulSoup

HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
}

API_URL = "https://nielseniq.com/wp-json/wp/v2/career_job"
# The endpoint is filtered by job_locations=14549, which the agent verified is the
# server-side "India" taxonomy term. Every record this endpoint returns is therefore an
# India role by construction -- the India-ness is guaranteed by the query, not re-derived.
API_PARAMS = {"job_locations": "14549", "per_page": 10, "_embed": "1"}
INDIA_LOCATION_TERM_ID = 14549


def parse_html(text):
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    text = text or ""
    soup = BeautifulSoup(text, "lxml")
    for tag in ("input", "script", "a"):
        raw_count = text.count("<" + tag)
        if raw_count >= 2 and len(soup.find_all(tag)) < raw_count // 2:
            return BeautifulSoup(text, "html.parser")
    return soup


_INDIA_CITY_FALLBACK = {
    "bengaluru": "Bengaluru", "bangalore": "Bangalore", "mumbai": "Mumbai", "delhi": "Delhi",
    "new delhi": "New Delhi", "gurugram": "Gurugram", "gurgaon": "Gurgaon", "noida": "Noida",
    "hyderabad": "Hyderabad", "chennai": "Chennai", "pune": "Pune", "kolkata": "Kolkata",
    "ahmedabad": "Ahmedabad",
}


def resolve_location(location_raw):
    # returns (city, state, country, country_code) -- all None if unresolvable, never guessed.
    if not location_raw:
        return (None, None, None, None)
    first_segment = location_raw.split(";")[0].strip()  # some platforms join multiple locations with ';'
    parts = [p.strip() for p in first_segment.split(",")]
    if len(parts) >= 2:
        # explicit "City, [State,] Country" format -- last segment is the country
        city = parts[0] or None
        state = parts[1] if len(parts) >= 3 else None
        country_raw = parts[-1]
        if country_raw.lower() in ("india", "in"):
            return (city, state, "India", "IN")
        return (city, state, country_raw or None, None)
    # no comma: bare city name -- only resolve via the small generic fallback dict, never guess otherwise
    bare = first_segment.lower()
    if bare in _INDIA_CITY_FALLBACK:
        return (_INDIA_CITY_FALLBACK[bare], None, "India", "IN")
    return (None, None, None, None)


def fetch_with_retries(url, params=None, timeout=30):
    session = requests.Session()
    last_resp = None
    for attempt in range(4):
        try:
            resp = session.get(url, headers=HEADERS, params=params, timeout=timeout)
            last_resp = resp
            if resp.status_code in (429, 500, 502, 503, 504, 403):
                if attempt < 3:
                    time.sleep(2 ** attempt)
                    continue
            return resp
        except requests.RequestException:
            if attempt < 3:
                time.sleep(2 ** attempt)
                continue
    return last_resp


def parse_date_text(text):
    if not text:
        return None
    txt = text.strip()
    fmts = [
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M:%SZ",
        "%Y-%m-%d",
        "%b %d %Y",
        "%b %d, %Y",
        "%d %b %Y",
        "%d %B %Y",
    ]
    for fmt in fmts:
        try:
            return datetime.strptime(txt, fmt).date().isoformat()
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(txt.replace("Z", "+00:00")).date().isoformat()
    except ValueError:
        return None


def normalize_url(u, base=None):
    if not u:
        return None
    return urljoin(base or API_URL, u)


def extract_job(record):
    if not isinstance(record, dict):
        return None

    title = record.get("title", {}).get("rendered") if isinstance(record.get("title"), dict) else None
    title = html_lib.unescape(title).strip() if isinstance(title, str) and title.strip() else None

    job_id = record.get("id")
    job_id = str(job_id).strip() if job_id is not None else None

    url = normalize_url(record.get("link"))
    date_posted_text = record.get("date")
    date_posted_text = html_lib.unescape(date_posted_text).strip() if isinstance(date_posted_text, str) and date_posted_text.strip() else None
    date_posted = parse_date_text(date_posted_text) if date_posted_text else None

    content_rendered = None
    content = record.get("content")
    if isinstance(content, dict):
        content_rendered = content.get("rendered")
    if isinstance(content_rendered, str):
        content_rendered = html_lib.unescape(content_rendered)

    # City comes from the embedded job_locations taxonomy terms (structured, reliable).
    # Country is India by construction: this record was returned by the India-scoped endpoint.
    city = state = None
    country, country_code = "India", "IN"
    embedded = record.get("_embedded") or {}
    for group in embedded.get("wp:term") or []:
        if not isinstance(group, list):
            continue
        for term in group:
            if not isinstance(term, dict) or term.get("taxonomy") != "job_locations":
                continue
            name = term.get("name")
            if not isinstance(name, str) or not name.strip():
                continue
            name = html_lib.unescape(name).strip()
            if name.lower() in ("india", "in") or term.get("id") == INDIA_LOCATION_TERM_ID:
                continue  # the country term itself, not a city
            if city is None:
                city = name

    # Fallback: parse the content header line, which is slash-separated
    # "Country / Country / State / City /" (NOT comma-separated).
    if city is None and content_rendered:
        soup = parse_html(content_rendered)
        first_p = soup.select_one("p")
        if first_p:
            txt = first_p.get_text(" ", strip=True)
            parts = [p.strip() for p in html_lib.unescape(txt).split("/") if p.strip()]
            # drop leading country repeats; last non-country segment is the city
            city_parts = [p for p in parts if p.lower() not in ("india", "in")]
            if city_parts:
                city = city_parts[-1]
                if len(city_parts) >= 2:
                    state = city_parts[-2]

    # employment_type: use the human-readable job_types taxonomy LABEL from _embedded,
    # never the raw numeric term id.
    employment_type = None
    for group in embedded.get("wp:term") or []:
        if not isinstance(group, list):
            continue
        for term in group:
            if isinstance(term, dict) and term.get("taxonomy") == "job_types":
                name = term.get("name")
                if isinstance(name, str) and name.strip():
                    employment_type = html_lib.unescape(name).strip()
                    break
        if employment_type:
            break

    return {
        "title": title,
        "job_id": job_id,
        "location": {"city": city, "state": state, "country": country, "country_code": country_code},
        "url": url,
        "apply_url": None,
        "date_posted": date_posted,
        "date_posted_text": date_posted_text,
        "job_description": content_rendered,
        "employment_type": employment_type,
        "work_type": None,
        "salary_range": None,
    }


def write_jsonl(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


def main():
    out_path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "output.jsonl")
    rows = []
    seen = set()
    try:
        page = 1
        while True:
            params = dict(API_PARAMS)
            params["page"] = page
            resp = fetch_with_retries(API_URL, params=params)
            if not resp:
                break
            if resp.status_code == 400:
                break
            if resp.status_code != 200:
                if resp.status_code in (403, 429, 500, 502, 503, 504):
                    break
                break
            try:
                data = resp.json()
            except ValueError:
                break
            if not isinstance(data, list):
                break

            new_count = 0
            for record in data:
                row = extract_job(record)
                if not row:
                    continue
                key = row.get("job_id") or row.get("url")
                if not key or key in seen:
                    continue
                seen.add(key)
                rows.append(row)
                new_count += 1

            if new_count == 0:
                break
            if not data:
                break
            page += 1
            time.sleep(0.35)

        write_jsonl(out_path, rows)
        return 0
    except Exception as e:
        try:
            write_jsonl(out_path, rows)
        except Exception:
            pass
        print(f"unrecoverable error: {e}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())